import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {Banner, Link} from '@primer/react'
import {useCallback} from 'react'

import {usePermissions} from '../contexts/PermissionsContext'
import {usePathsContext} from '../contexts/PathsContext'
import {usePolicyMutation} from '../hooks/use-policy-mutation'
import type {ModelsDefaultPolicyData} from '../routes/overview-route'

type ModelsDefaultPolicyProps = {
  modelsDefaultPolicy: ModelsDefaultPolicyData
}

const valueNameMap = {
  enabled: 'Enabled',
  no_policy: 'Optional',
  disabled: 'Disabled',
}

function getValueLabel(value: string): string {
  return valueNameMap[value as keyof typeof valueNameMap] || value
}

const modes = [
  {
    name: 'enabled',
    label: valueNameMap.enabled,
    description: 'New models will be automatically enabled for all organizations.',
  },
  {
    name: 'no_policy',
    label: valueNameMap.no_policy,
    description: 'New models will be available but disabled by default. Organizations can choose to enable them.',
  },
  {
    name: 'disabled',
    label: valueNameMap.disabled,
    description: 'New models will be disabled. You must manually enable each new model.',
  },
]

export function ModelsDefaultPolicy({modelsDefaultPolicy}: ModelsDefaultPolicyProps) {
  const {canWrite} = usePermissions()
  const {policyUpdatePath} = usePathsContext()

  const {value, updateValue, error, clearError, isUpdating} = usePolicyMutation({
    policyUpdatePath,
    policy: modelsDefaultPolicy.manages,
    initialValue: modelsDefaultPolicy.value,
    errorMessage: 'There was a problem updating the default models policy.',
  })

  const handleModeChange = useCallback(
    (nextValue: string) => {
      if (!canWrite || isUpdating) {
        return
      }
      updateValue(nextValue)
    },
    [canWrite, isUpdating, updateValue],
  )

  if (!modelsDefaultPolicy.visible) {
    return null
  }

  return (
    <>
      {error && <Banner variant="critical" title="Error" hideTitle description={error} onDismiss={clearError} />}
      <EnterpriseControlGroup>
        <EnterpriseControlGroup.Selector
          title={modelsDefaultPolicy.displayName}
          description={
            <>
              When a{' '}
              <Link href={modelsDefaultPolicy.helpUrl} className="Link--inTextBlock">
                new model
              </Link>{' '}
              is released, this policy is applied automatically. You can override individual models on the detail page.
            </>
          }
          modes={modes}
          selectedMode={value}
          onModeChange={handleModeChange}
          disabled={!canWrite || isUpdating}
        />
        <div className="tmp-px-3 tmp-pb-3">
          <Banner
            variant="info"
            title={`On August 21 all models set to 'unconfigured' will be set to ${getValueLabel(value)}`}
            hideTitle
            description={
              <>
                On August 21 all models set to &apos;unconfigured&apos; will be set to{' '}
                <strong>{getValueLabel(value).toLowerCase()}</strong>
              </>
            }
          />
        </div>
      </EnterpriseControlGroup>
    </>
  )
}
