import {useMemo, useState} from 'react'
import {Button, IconButton, Label, ActionMenu, ActionList} from '@primer/react'
import {XIcon, AiModelIcon, FoldIcon, UnfoldIcon} from '@primer/octicons-react'
import {PanelList} from '@github-ui/panel-list'
import {ModelSelector} from '../ModelSelector'
import {type CopilotModelValue, ModelValue, type ModelWithValue} from '../../types'
import {useModels} from '../../hooks/use-models'
import {PublisherIcon} from '../PublisherIcon'
import {useEnabledFeatures} from '../../contexts/EnabledFeaturesContext'
import {usePermissions} from '../../contexts/PermissionsContext'
import {useSettings} from '../../hooks/use-settings'
import {useBannerContext} from '../../contexts/BannerContext'
import {useLoading} from '../../contexts/LoadingContext'
import {renderMarkdownLinks} from '../../utils/render-markdown-links'

function getSelectedDisplayText(value: ModelValue, isUnconfiguredSeparate: boolean = false): string {
  switch (value) {
    case ModelValue.NoPolicy:
      return 'Optional'
    case ModelValue.Enabled:
      return 'Enabled'
    case ModelValue.Unconfigured:
      return isUnconfiguredSeparate ? 'Unconfigured' : 'Disabled'
    case ModelValue.Disabled:
    default:
      return 'Disabled'
  }
}

type ModelsPanelProps = {
  title?: string
  selectedModels: CopilotModelValue
  showEnterpriseHeader?: boolean
  setModels(updatedModels: CopilotModelValue): void
  showDisabledModels?: boolean
  showStatus?: boolean
}

export function ModelsPanel({
  title,
  selectedModels: currentValue,
  showEnterpriseHeader,
  setModels,
  showDisabledModels = false,
  showStatus = false,
}: ModelsPanelProps) {
  const {isSyncing, models, selectedModels} = useModels(currentValue)
  const {setting} = useSettings()
  // !!isUnconfiguredSeparate means they're visible above the fold, and !isUnconfiguredSeparate means they're hidden
  const {isUnconfiguredSeparate} = useEnabledFeatures()
  const {canWrite} = usePermissions()
  const [isCollapsed, setIsCollapsed] = useState(true)
  const {banner} = useBannerContext()
  const {isLoading} = useLoading()

  const modelsBelowTheFold = useMemo(() => models.filter(model => model.value === ModelValue.Disabled), [models])

  // Between the collapsed toggle and toggled separate unconfigured state, this feels most "legible" as nested ifs
  const visibleModels = useMemo(() => {
    // if disabled models are visible (overview route) and unconfigured is separate, show everything
    if (showDisabledModels) {
      if (isUnconfiguredSeparate) {
        if (isCollapsed) {
          return models.filter(model => model.value !== ModelValue.Disabled)
        } else {
          return models
        }
        // else hide unconfigured models
      } else if (isCollapsed) {
        return models.filter(model => model.value === ModelValue.Enabled || model.value === ModelValue.NoPolicy)
      } else {
        return models.filter(model => model.value !== ModelValue.Unconfigured)
      }
      // if !showDisabledModels (rule route), show all but explicitly disabled models
    } else {
      if (isUnconfiguredSeparate) {
        return models.filter(model => model.value !== ModelValue.Disabled)
        // else hide disabled models _and_ unconfigured models
      } else {
        return models.filter(model => model.value !== ModelValue.Unconfigured && model.value !== ModelValue.Disabled)
      }
    }
  }, [isCollapsed, isUnconfiguredSeparate, models, showDisabledModels])

  const pluralizedBelowTheFoldModels = modelsBelowTheFold.length === 1 ? 'model' : 'models'
  const foldText = `${isCollapsed ? 'Show' : 'Hide'} ${modelsBelowTheFold.length} disabled ${pluralizedBelowTheFoldModels}`

  return (
    <PanelList isLoading={isSyncing || isLoading} isEmpty={visibleModels.length + modelsBelowTheFold.length === 0}>
      {showEnterpriseHeader && (
        <PanelList.Header
          title="Enterprise-wide enabled models"
          subtitle={`Selected Copilot models are available across every organization in ${setting?.resource.name ?? ''}`}
        />
      )}
      <PanelList.BoxHeader title={title || 'Models'}>
        <PanelList.BoxHeader.Actions>
          <ModelSelector
            key={[...visibleModels, ...modelsBelowTheFold].map(m => `${m.name}:${m.value}`).join(',')}
            isSyncing={isSyncing || isLoading}
            models={models}
            selectedModels={selectedModels}
            setModels={setModels}
            disabled={!canWrite}
          />
        </PanelList.BoxHeader.Actions>
        {showStatus && banner ? (
          <PanelList.BoxHeader.InlineMessage size="small" variant={banner.type}>
            {banner.message}
          </PanelList.BoxHeader.InlineMessage>
        ) : null}
      </PanelList.BoxHeader>
      <PanelList.Rows>
        <ModelRows models={visibleModels} setModels={setModels} inlineDisable={isCollapsed} />
        {modelsBelowTheFold.length > 0 && (
          <li className="Box-row d-flex flex-justify-center flex-items-center p-0">
            <Button
              className="width-full fgColor-muted"
              leadingVisual={isCollapsed ? UnfoldIcon : FoldIcon}
              variant="invisible"
              onClick={() => setIsCollapsed(!isCollapsed)}
            >
              {foldText}
            </Button>
          </li>
        )}
      </PanelList.Rows>
      <PanelList.Blankslate heading="No models have been added yet" icon={AiModelIcon} />
    </PanelList>
  )
}

function ModelRows({
  models,
  inlineDisable,
  setModels,
}: {
  models: ModelWithValue[]
  inlineDisable?: boolean
  setModels: ModelsPanelProps['setModels']
}) {
  return models.map(model => (
    <PanelList.Row key={model.name}>
      {model.publisher && (
        <PanelList.Row.LeadingVisual>
          <PublisherIcon publisher={model.publisher} />
        </PanelList.Row.LeadingVisual>
      )}
      <div className="d-flex flex-column gap-1">
        <div>
          <span className="text-semibold">{model.displayName}</span>{' '}
          {model.isPreview ? <Label variant="success">Preview</Label> : null}
        </div>
        {model.warningMarkdown && (
          <div className="text-small text-muted">{renderMarkdownLinks(model.warningMarkdown)}</div>
        )}
      </div>
      <PanelList.Row.Actions>
        <ModelValueMenu model={model} setModels={setModels} inlineDisable={!!inlineDisable} />
      </PanelList.Row.Actions>
    </PanelList.Row>
  ))
}

type ModelValueMenuProps = {
  model: ModelWithValue
  inlineDisable?: boolean
  setModels: ModelsPanelProps['setModels']
}

function ModelValueMenu({model, inlineDisable = false, setModels}: ModelValueMenuProps) {
  const {isUnconfiguredSeparate} = useEnabledFeatures()
  const {canWrite} = usePermissions()
  const disabled = !canWrite
  return (
    <div className="d-flex flex-row flex-items-center gap-0">
      <ActionMenu>
        <ActionMenu.Button variant="invisible" disabled={disabled}>
          {getSelectedDisplayText(model.value, isUnconfiguredSeparate)}
        </ActionMenu.Button>
        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="single">
            <ActionList.Item
              selected={model.value === ModelValue.Enabled}
              onSelect={() => setModels({[model.name]: ModelValue.Enabled})}
              disabled={disabled}
            >
              Enabled
              <ActionList.Description variant="block">
                This model is always enabled. Organizations cannot disable it.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item
              selected={model.value === ModelValue.NoPolicy}
              onSelect={() => setModels({[model.name]: ModelValue.NoPolicy})}
              disabled={disabled}
            >
              Optional
              <ActionList.Description variant="block">
                This model is disabled by default. Organizations can choose to enable it.
              </ActionList.Description>
            </ActionList.Item>
            {!inlineDisable && (
              <ActionList.Item
                selected={
                  model.value === ModelValue.Disabled ||
                  (!isUnconfiguredSeparate && model.value === ModelValue.Unconfigured)
                }
                onSelect={() => setModels({[model.name]: ModelValue.Disabled})}
                disabled={disabled}
              >
                Disabled
                <ActionList.Description variant="block">
                  Organizations or users will not have access to this feature. It cannot be enabled at the organization
                  level.
                </ActionList.Description>
              </ActionList.Item>
            )}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      {inlineDisable && (
        <IconButton
          icon={XIcon}
          aria-label={`Remove ${model.displayName} model`}
          variant="invisible"
          disabled={disabled}
          onClick={() => setModels({[model.name]: ModelValue.Disabled})}
        />
      )}
    </div>
  )
}
