import {type BaseConditionExpression, type ConditionExpression, type Rule, RuleType, type Setting} from '../types'

export const SettingActionType = {
  INITIALIZE: 'INITIALIZE',
  SET_VALUE: 'SET_VALUE',
  ADD_RULE: 'ADD_RULE',
  UPDATE_RULE: 'UPDATE_RULE',
  REMOVE_RULE: 'REMOVE_RULE',
} as const
export type SettingActionType = (typeof SettingActionType)[keyof typeof SettingActionType]

export type SettingAction<Value, AllowedTypes extends RuleType, Condition extends BaseConditionExpression> =
  | {
      type: 'INITIALIZE'
      payload: Setting<Value, AllowedTypes, Condition>
    }
  | {
      type: 'SET_VALUE'
      payload: Value
    }
  | {
      type: 'ADD_RULE'
      payload: Rule<Value, AllowedTypes, Condition>
    }
  | {
      type: 'UPDATE_RULE'
      payload: Rule<Value, AllowedTypes, Condition>
    }
  | {
      type: 'REMOVE_RULE'
      payload: Rule<Value, AllowedTypes, Condition>
    }

/**
 * @see {@link ../hooks/use-setting.ts}
 */
export const createSettingReducer =
  <Value, AllowedTypes extends RuleType, Condition extends BaseConditionExpression = ConditionExpression>() =>
  (
    state: Setting<Value, AllowedTypes, Condition> | undefined,
    action: SettingAction<Value, AllowedTypes, Condition>,
  ): Setting<Value, AllowedTypes, Condition> | undefined => {
    if (action.type === SettingActionType.INITIALIZE) {
      return action.payload
    }
    if (!state) {
      // eslint-disable-next-line no-console
      console.warn(
        `initialState was not provided and ${SettingActionType.INITIALIZE} has not been called, actions will not be dispatched`,
      )
      return undefined
    }
    switch (action.type) {
      case SettingActionType.SET_VALUE:
        return {
          ...state,
          value: action.payload,
        }
      case SettingActionType.ADD_RULE:
        return {
          ...state,
          rules: [...state.rules, action.payload],
        }
      case SettingActionType.UPDATE_RULE: {
        const ruleIndex = state.rules.findIndex(rule => rule.id === action.payload.id)
        if (ruleIndex === -1) return state
        return {
          ...state,
          rules: [...state.rules.slice(0, ruleIndex), action.payload, ...state.rules.slice(ruleIndex + 1)],
        }
      }
      case SettingActionType.REMOVE_RULE: {
        const ruleIndex = state.rules.findIndex(rule => rule.id === action.payload.id)
        if (ruleIndex === -1) return state
        return {
          ...state,
          rules: [...state.rules.slice(0, ruleIndex), ...state.rules.slice(ruleIndex + 1)],
        }
      }
      default:
        return state
    }
  }
