import {useCallback, useMemo, useReducer, useRef} from 'react'
import {createSettingReducer} from '../reducers/setting-reducer'
import {type BaseConditionExpression, type ConditionExpression, type Rule, RuleType, type Setting} from '../types'

export type SettingContextType<
  Value,
  AllowedTypes extends RuleType,
  Condition extends BaseConditionExpression = ConditionExpression,
> = {
  setting?: Setting<Value, AllowedTypes, Condition>
  initialize: (setting: Setting<Value, AllowedTypes, Condition>) => void
  setValue: (value: Value) => void
  addRule: (rule: Omit<Rule<Value, AllowedTypes, Condition>, 'id'>) => void
  updateRule: (rule: Rule<Value, AllowedTypes, Condition>) => void
  removeRule: (rule: Rule<Value, AllowedTypes, Condition>) => void
}

/**
 * @example
   import {type PropsWithChildren, createContext, useContext} from 'react'
   import type {Setting} from '../types'
   import {
     type SettingContextType,
     useSetting
   } from '@github-ui/ruleset-settings-state/hooks/use-setting'

   type CopilotModelValue = string[]
   type CopilotModelAllowedTypes = 'add' | 'allow_add'

   type ContextType = SettingContextType<CopilotModelValue, CopilotModelAllowedTypes>
   export const SettingContext = createContext<ContextType | undefined>(undefined)

   type CopilotModelSetting = Setting<CopilotModelValue, CopilotModelAllowedTypes>
   type InitialState = Pick<CopilotModelSetting, 'resource' | 'type' | 'value'>

   export function SettingProvider({
     children,
     initialState,
   }: PropsWithChildren<{initialState: InitialState}>) {
     const value = useSetting<CopilotModelValue, CopilotModelAllowedTypes>(initialState)
     return <SettingContext.Provider value={value}>
       {children}
     </SettingContext.Provider>
   }

   export function useSettingContext() {
     const context = useContext(SettingContext)
     if (!context) {
       throw new Error('useSettingContext must be used within a SettingProvider')
     }
     return context
   }
 */
export const useSetting = <
  Value,
  AllowedTypes extends RuleType,
  Condition extends BaseConditionExpression = ConditionExpression,
>(
  initialState?: Omit<Setting<Value, AllowedTypes, Condition>, 'id' | 'rules'>,
): SettingContextType<Value, AllowedTypes, Condition> => {
  const localId = useRef(-1)
  const settingReducer = createSettingReducer<Value, AllowedTypes, Condition>()
  const [state, dispatch] = useReducer(
    settingReducer,
    initialState
      ? {
          rules: [] as Array<Rule<Value, AllowedTypes, Condition>>,
          // eslint-disable-next-line react-hooks/refs
          id: localId.current--,
          ...initialState,
        }
      : undefined,
  )

  const initialize = useCallback(
    (setting: Setting<Value, AllowedTypes, Condition>) =>
      dispatch({
        type: 'INITIALIZE',
        payload: setting,
      }),
    [dispatch],
  )

  const setValue = useCallback(
    (value: Value) =>
      dispatch({
        type: 'SET_VALUE',
        payload: value,
      }),
    [dispatch],
  )

  const addRule = useCallback(
    (rule: Omit<Rule<Value, AllowedTypes, Condition>, 'id'>) =>
      dispatch({
        type: 'ADD_RULE',
        payload: {
          id: localId.current--,
          ...rule,
        },
      }),
    [dispatch],
  )

  const updateRule = useCallback(
    (rule: Rule<Value, AllowedTypes, Condition>) =>
      dispatch({
        type: 'UPDATE_RULE',
        payload: rule,
      }),
    [dispatch],
  )

  const removeRule = useCallback(
    (rule: Rule<Value, AllowedTypes, Condition>) =>
      dispatch({
        type: 'REMOVE_RULE',
        payload: rule,
      }),
    [dispatch],
  )

  return useMemo(
    () => ({
      setting: state,
      initialize,
      setValue,
      addRule,
      updateRule,
      removeRule,
    }),
    [state, initialize, setValue, addRule, updateRule, removeRule],
  )
}
