import {type PropsWithChildren, createContext, use, useCallback, useMemo, useState} from 'react'

export type LoadingContextType = {
  isLoading: boolean
  setIsLoading: (loading: boolean) => void
}
export const LoadingContext = createContext<LoadingContextType | undefined>(undefined)

export function LoadingProvider({children}: PropsWithChildren) {
  const [incrementalLoadingState, setIncrementalLoadingState] = useState<number>(0)
  const setIsLoading = useCallback(
    (isLoading: boolean) => {
      const increment = isLoading ? 1 : -1
      setIncrementalLoadingState(current => Math.max(current + increment, 0))
    },
    [setIncrementalLoadingState],
  )
  const value = useMemo(
    () => ({
      isLoading: incrementalLoadingState > 0,
      setIsLoading,
    }),
    [incrementalLoadingState, setIsLoading],
  )
  return <LoadingContext value={value}>{children}</LoadingContext>
}

export function useLoading(): LoadingContextType {
  const context = use(LoadingContext)
  if (typeof context === 'undefined') {
    throw new Error('useLoading must be used within a LoadingProvider')
  }
  return context
}
