import {useCallback, useMemo} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useIsRouteMounted} from '@github-ui/react-core/future/use-is-route-mounted'
import {ModelsPanel} from '../components/panels/ModelsPanel'
import {RulesPanel} from '../components/panels/RulesPanel'
import {ModelsDefaultPolicy} from '../components/ModelsDefaultPolicy'
import {useSettings} from '../hooks/use-settings'
import type {CopilotModelSetting, CopilotModelValue} from '../types'
import {overviewRoute, stafftoolsOverviewRoute} from './overview-route'

export function Overview() {
  const {setting, updateSetting, setValue} = useSettings()
  const isStafftools = useIsRouteMounted(stafftoolsOverviewRoute)
  const {data: routePayload} = useRouteQuery(isStafftools ? stafftoolsOverviewRoute : overviewRoute, 'mainQuery')

  const selectedModels = useMemo(() => setting?.value ?? {}, [setting?.value])

  const setModels = useCallback(
    (updatedModels: CopilotModelValue) => {
      setValue({
        ...selectedModels,
        ...updatedModels,
      })
      updateSetting({
        ...setting,
        value: {
          ...selectedModels,
          ...updatedModels,
        },
      } as CopilotModelSetting)
    },
    [selectedModels, setValue, setting, updateSetting],
  )

  return (
    <>
      {routePayload.modelsDefaultPolicy && (
        <ModelsDefaultPolicy modelsDefaultPolicy={routePayload.modelsDefaultPolicy} />
      )}
      <ModelsPanel
        selectedModels={selectedModels}
        setModels={setModels}
        showEnterpriseHeader
        showDisabledModels
        showStatus
      />
      <RulesPanel />
    </>
  )
}
