import {mainQuery} from '@github-ui/react-core/future/main-query'
import type {BaseOrganization} from '@github-ui/org-selector'
import type {CopilotModelSetting, Model} from '../types'
import {defaultModelSettingsAppBuilder} from '../config/app-builder'

export type ModelsDefaultPolicyData = {
  manages: string
  value: string
  displayName: string
  helpUrl: string
  visible: boolean
}

export type OverviewResponse = {
  models: Model[]
  organizations: BaseOrganization[]
  settings: CopilotModelSetting
  modelsDefaultPolicy?: ModelsDefaultPolicyData
}

export const overviewRoute = defaultModelSettingsAppBuilder.createQueryRouteConfig('overviewRoute', {
  path: '/enterprises/:slug/ai-controls/copilot/models',
  queries: [mainQuery<OverviewResponse>()],
})

export const stafftoolsOverviewRoute = defaultModelSettingsAppBuilder.createQueryRouteConfig(
  'stafftoolsOverviewRoute',
  {
    path: '/stafftools/enterprises/:slug/copilot/default_models',
    queries: [mainQuery<OverviewResponse>()],
  },
)
